    ["53406a7"] = "Dire Bear Form에 한 번만 들어가고, 다시 눌러도 나가지 않습니다.",
    ["b18da61"] = "주시 대상에게, 다음 커서 대상에게, 그다음 현재 대상에게 Growl.",
    ["beb6029"] = "Nature's Swiftness 후 곧바로 Healing Touch: 즉시 긴급 치유 (변신을 풀고 시전을 멈춥니다).",
    ["8c5c182"] = "전투 중에는 매크로를 만들 수 없습니다. 나중에 다시 시도하세요.",
    ["e3c93a8"] = "매크로: %d개 생성, %d개 갱신%s. /macro 로 열어 행동 단축바로 끌어 놓으세요.",
    ["99effc3"] = "%d개 생성 안 됨 (캐릭터 매크로가 이미 18개)",
    ["530c645"] = "이 전문화에는 매크로가 없습니다.",
    ["1e74c8f"] = "BuildBeast가 캐릭터에 매크로 %s개를 만듭니다:\n%s\n\n이미 있으면 갱신합니다. 그다음 행동 단축바로 끌어 놓으세요.",
    ["d8354a3"] = "만들기",
    ["160009a"] = "취소",
    ["054716f"] = "전사",
    ["3e76e85"] = "성기사",
    ["69c8129"] = "사냥꾼",
    ["dd6c053"] = "도적",
    ["3a3f441"] = "사제",
    ["fabeb14"] = "주술사",
    ["a5a0a92"] = "마법사",
    ["8b0635d"] = "흑마법사",
    ["3d8e8ed"] = "드루이드",
    ["ce774d9"] = "예",
    ["c2f3f48"] = "아니오",
    ["672c529"] = "비슷함",
    ["656ff24"] = "Bear Form, Growl, Maul (직업 퀘스트), Nature's Grasp, Demoralizing Roar",
    ["50d1ea3"] = "Bash; Cure Poison 퀘스트",
    ["2290f2a"] = "Swipe; Aquatic Form 퀘스트",
    ["227f378"] = "Faerie Fire (이제 변신 상태에서도 사용), Hibernate",
    ["469f184"] = "Cat Form (퀘스트), Prowl, Claw, Rip, Shred, Starfire, Rebirth, Omen of Clarity",
    ["eda7053"] = "자신에게 Mark of the Wild. Wrath로 시작하고 계속 시전하세요. 마나가 낮으면 무기로 몬스터를 마무리해 마나를 회복합니다. 전투 사이에 Healing Touch로 치유하세요.",
    ["3d495a9"] = "자신에게 Mark of the Wild와 Thorns를 유지하고 전투 전에 Rejuvenation을 거세요. Wrath로 시작하고 Moonfire를 더한 뒤 Wrath를 계속 쓰세요. 붐비는 지역에서는 즉시 시전인 Moonfire로 시작하세요.",
    ["bb21cc8"] = "직업 퀘스트가 Bear Form, Growl, Maul을 줍니다. Nature's Grasp는 다음에 나를 때리는 몬스터를 속박하고, Demoralizing Roar는 곰 변신용입니다.",
    ["a9ba21f"] = "Enrage는 분노를 즉시, 그리고 10초 뒤에 더 주지만 방어력을 낮춥니다.",
    ["9c7f3ca"] = "Feral은 표범과 곰 전문화이며 가장 매끄럽게 레벨업합니다. Prowl과 Dash가 목표에서 목표로 데려다 주어 마나 때문에 거의 멈추지 않습니다. Bear Form에서는 자신에게 Mark of the Wild와 Thorns, 타격으로 얻은 분노로 다음 타격에 피해를 더하는 Maul을 쓰세요. 여러 몬스터에게는 Demoralizing Roar로 약화시키세요.",
    ["ce230c2"] = "Bear Form에서: 전투 전에 Enrage(방어력 감소 영향이 작음), Faerie Fire로 몬스터 방어력 감소, Swipe가 채움 기술이고 Maul이 남은 분노를 씁니다. 여러 몬스터에게는 먼저 Demoralizing Roar, 그다음 Swipe.",
    ["78a0920"] = "Cat Form: 먼저 Mark of the Wild와 Thorns. Prowl에서 Shred로 시작(Prowl이 몬스터 뒤로 데려갑니다), 그다음 Faerie Fire, 그다음 연계 점수를 쌓는 Claw 또는 뒤에 있을 때 Shred. 연계 점수 4개 이상이면 몬스터가 충분히 오래 살 때 Rip. 여러 몬스터에게는 Bear Form이 더 낫습니다. 표범 변신에는 둘 이상을 때리는 기술이 없습니다.",
    ["540175c"] = "Rake: Prowl에서 Shred로 시작, Faerie Fire, 그다음 Rake를 쓰고 오래 사는 몬스터에게는 그 출혈을 항상 유지하세요. 이어서 뒤에서 Claw 또는 Shred. 점수 4개 이상이면 몬스터가 살아 있을 때 Rip, 마무리는 Ferocious Bite.",
    ["87e3251"] = "Lacerate(곰): 최대 5번 중첩되는 출혈입니다. 몬스터 하나를 상대할 때는 채움 기술이고 Maul이 남은 분노를 씁니다. 여러 몬스터에게는 Demoralizing Roar, 그다음 Swipe. Blood Frenzy: 곰에서는 치명타마다 분노 5, 표범에서는 연계 점수 기술의 치명타가 점수를 하나 더 줍니다.",
    ["25dc320"] = "Predatory Discipline: Ferocious Bite가 남는 기력에서 여전히 피해를 얻지만 기력을 소모하지는 않습니다.",
    ["042c952"] = "Ravage: Prowl에서 Ravage로 시작(몬스터 뒤에 있어야 함), 그다음 Faerie Fire, 출혈을 항상 유지한 Rake, 그다음 뒤에서 Claw 또는 Shred. 점수 4개 이상이면 마무리로 Rip 또는 Ferocious Bite. 기력이 가득 찬 상태로 시작하면 Poised가 첫 타격의 기력을 10 줄여 줍니다.",
    ["4560b4d"] = "Dire Bear Form: 전투 전에 Enrage, Faerie Fire, 재사용 때마다 Primal Bite(재사용 6초에 위협이 큰 강한 물기), 몬스터 하나일 때는 중간에 Lacerate, 나머지는 Maul로 소모. 여러 몬스터에게는 Lacerate 대신 Demoralizing Roar와 Swipe.",
    ["ff10d54"] = "표범: 기력이 50 미만일 때 Shifting Power(마나를 기력 40으로 바꿈, 재사용 8초).",
    ["0d8ecd7"] = "Feral은 무엇보다 무기의 초당 피해를 원합니다. 변신이 그것을 기반으로 하고 무기 속도는 중요하지 않기 때문입니다. 그다음 적중, 치명타, 민첩성, 힘.",
    ["4a841e3"] = "Guardian은 곰입니다. Feral과 같은 특성 계획을 씁니다. 자신에게 Mark of the Wild와 Thorns를 건 Bear Form, 타격으로 얻은 분노가 Maul을 냅니다. 여러 몬스터에게는 Demoralizing Roar.",
    ["7b551a8"] = "전투 전에 Enrage, 몬스터에게 Faerie Fire, 채움은 Swipe, 남은 분노는 Maul. 여러 몬스터에게는 Demoralizing Roar 다음 Swipe.",
    ["af4c8fb"] = "Lacerate는 몬스터 하나를 상대할 때의 채움 기술입니다(최대 5번 중첩). Maul이 남은 분노를 씁니다. 여러 몬스터에게는 Demoralizing Roar와 Swipe.",
    ["5213241"] = "Dire Bear Form: 전투 전에 Enrage, Faerie Fire, 재사용 때마다 Primal Bite(6초, 위협 큼), 몬스터 하나일 때는 중간에 Lacerate, 나머지는 Maul. 여러 몬스터에게는 Lacerate 대신 Demoralizing Roar와 Swipe.",
    ["fc61247"] = "곰은 무기의 초당 피해(속도는 중요하지 않음)를 원하고, 그다음 적중, 치명타, 민첩성, 힘입니다. 곰 변신에는 힘과 주문력도 괜찮고, 탱킹한다면 체력이 더 중요합니다.",
    ["25acd2a"] = "Balance와 Restoration은 똑같이 시작합니다: Improved Wrath(시전 시간 0.5초 감소와 마나 절반)와 Nature's Focus. Balance는 느리게 시작하지만 모든 몬스터에게 Moonfire에 Insect Swarm을 더하면 빨라집니다.",
    ["9c1fb9f"] = "자신에게 Mark of the Wild와 Thorns, 전투 전에 Rejuvenation. Wrath로 시작하거나 지역이 붐비면 Moonfire로 시작. 몬스터에게 Moonfire와 Insect Swarm(적중 확률도 낮추는 DOT), 그다음 Wrath. 치유가 필요하면 Regrowth, 두 번째 몬스터가 오기 전에 Nature's Grasp.",
    ["7f51b3b"] = "싸우는 모든 몬스터에게 Moonfire와 Insect Swarm, 그다음 Wrath. 몬스터가 셋 이상이면 Hurricane.",
    ["c845919"] = "몬스터가 셋 이상이면 Barkskin, 그다음 Hurricane.",
    ["d66aa4c"] = "Eclipse: Wrath마다 다음 Starfire 두 번의 시전 시간이 0.5초 줄어서 마침내 Starfire가 연계에 들어옵니다. Wrath 한 번 다음에 Starfire 두 번.",
    ["7e94c11"] = "Moonkin Form: 방어력이 높고, 파티에 치명타 3%, Omen of Clarity가 두 배 자주 발동합니다. 이 상태에서는 치유 주문을 쓸 수 없으니 Regrowth를 위해 나왔다가 다시 들어가세요. 연계: Moonfire와 Insect Swarm, 그다음 Wrath 한 번과 Starfire 두 번.",
    ["ef6797a"] = "Balance와 Restoration은 주문력이 먼저, 그다음 지능, 치명타, 정신력입니다. Restoration은 60레벨에서 치유량을 더합니다. 시전자용 지팡이는 진영 퀘스트에서 나올 수 있습니다.",
    ["a91a8ac"] = "Restoration은 치유가 몬스터를 죽이지 못하므로 레벨업이 가장 느립니다. Balance나 Feral로 레벨업하면서도 던전에서 치유할 수 있습니다.",
    ["7a2110b"] = "자신에게 Mark of the Wild와 Thorns, 전투 전에 Rejuvenation. 붐비는 지역에서는 Wrath 또는 Moonfire로 시작, 그다음 몬스터에게 Moonfire와 Insect Swarm, 그리고 Wrath. 치유가 필요하면 Regrowth, 두 번째 몬스터가 오기 전에 Nature's Grasp.",
    ["937f66e"] = "Swiftmend: 내 Rejuvenation이나 Regrowth가 걸린 대상을 즉시 치유합니다. 피해를 입으면 내 Rejuvenation에 Swiftmend, 더 필요하면 Regrowth. 몬스터가 셋 이상이면 Hurricane.",
    ["2061d06"] = "Nature's Swiftness: 다음 자연 주문이 즉시 시전됩니다. 큰 치유가 당장 필요한 순간을 위해 연계에서 빼 두세요.",
    ["1164b95"] = "Wild Growth: 대상과 그 파티를 7초에 걸쳐 치유하며 처음이 더 강합니다. 파티에서 둘 이상이 다쳤을 때 쓰세요.",
    ["8f8a34a"] = "Aspect of the Hawk, 소환수 길들이기 (직업 퀘스트: Tame Beast, Call Pet, Feed Pet, Revive Pet)",
    ["2b3db50"] = "Auto Shot은 자동으로 시작됩니다. 매 사격 전에 0.5초 가만히 서서 몬스터가 오게 하세요. 닿으면 Raptor Strike. 8미터 안에서는 원거리 사격이 되지 않습니다.",
    ["9329f10"] = "시작할 때 Serpent Sting을 더하되 오래 사는 몬스터에게만. 몇 초 안에 죽으면 피해가 낭비됩니다.",
    ["d2b7bf1"] = "전투 전에 Hunter's Mark, 그다음 Serpent Sting. 마나가 있으면 Arcane Shot.",
    ["85f72cd"] = "중심은 Auto Shot이고 마나가 있으면 Arcane Shot. 전투 전에 Hunter's Mark, 시작으로 Serpent Sting. 몬스터가 달려오는 동안 Concussive Shot으로 감속시키고, 닿으면 Raptor Strike.",
    ["71067ff"] = "소환수가 있습니다. 몇 초 먼저 보낸 뒤 Serpent Sting. 항상 Aspect of the Hawk를 유지하고 소환수에게 먹이를 주세요. 몬스터가 나를 향하면 Concussive Shot, 최후의 수단으로 Raptor Strike.",
    ["bb6f64b"] = "Rapid Fire(15초 동안 공격 속도 +40%)는 연계에서 빠집니다. 필요한 전투를 위해 아껴 두세요.",
    ["ebe54cf"] = "중심은 준비될 때마다 Aimed Shot입니다(시전 2초, Multi-Shot과 공유하는 재사용 6초). 빈틈에는 Auto Shot. 전투 전에 Hunter's Mark, 소환수를 앞세우고 Serpent Sting. 마나가 있으면 Arcane Shot. 몬스터가 닿으면 Disengage. 여러 몬스터에게는 Aimed Shot 대신 Multi-Shot.",
    ["c943332"] = "중심은 매(Summon Hawk)입니다. 매는 18초 지속되고 둘까지 나와 있을 수 있으며, 둘 중 하나가 사라지면 새 매를 소환하세요. 그다음 준비되면 Aimed Shot, 빈틈에는 Auto Shot. Arcane Shot은 매와 같은 재사용 대기시간을 쓰므로 매 다음에 기다립니다. 나머지는 앞과 같습니다.",
    ["ab9f050"] = "Intimidation을 더하세요. 몬스터가 나를 향하면 기절시키고 소환수에게 위협을 줍니다. 준비되지 않았으면 Disengage. 여러 몬스터에게는 먼저 Explosive Trap, 그다음 Aimed Shot 재사용 시간에 Multi-Shot.",
    ["bf06335"] = "Bestial Wrath(2분)와 Volley는 연계에서 빠집니다. 위험한 전투나 큰 무리에서 직접 사용하세요. 42레벨부터는 거의 모든 포인트가 Marksmanship로 가지만 연계는 바뀌지 않습니다.",
    ["e096af7"] = "Beast Mastery는 멀리서 쏩니다. 원거리 무기 DPS가 중요하고 그다음 민첩성. 근접 무기는 능력치 때문에만 필요합니다.",
    ["b35c3c9"] = "중심은 준비될 때마다 Aimed Shot이고 빈틈에는 Auto Shot. 소환수의 선공 이후 첫 사격이 가장 강해야 합니다. Rapid Killing이 대기 중이면 Aimed Shot입니다. 전투 전에 Hunter's Mark와 소환수 선공, 모든 몬스터에게 Serpent Sting. Serpent Sting이 걸린 채 죽으면 20초 안의 다음 사격이 최대 20% 더 강해지기 때문입니다. 마나가 있으면 Arcane Shot. 몬스터가 닿으면 Disengage. 여러 몬스터에게는 Aimed Shot 대신 Multi-Shot.",
    ["cf4e14e"] = "전투 전에 Hunter's Mark 외에 Trueshot Aura도.",
    ["51e16cf"] = "Sniper Shot은 가장 강한 사격입니다. 시전 4초, 재사용 15초, 최대 45미터, 그리고 10초 동안 이어지는 세 발이 10미터 더 멀리 나갑니다. 시전할 시간이 있을 때 소환수 선공 후 첫 사격으로 쓰고, Rapid Killing이 대기 중이면 더 좋습니다. 아니면 Aimed Shot. 여러 몬스터에게는 먼저 Explosive Trap, 그다음 Aimed Shot 재사용 시간에 Multi-Shot.",
    ["c8aaa16"] = "중심은 매(Summon Hawk)입니다. 둘 중 하나가 사라질 때마다 새로 소환. 그다음 준비되면 Aimed Shot, 빈틈에는 Auto Shot. 시간이 있으면 첫 사격으로 Sniper Shot. Arcane Shot은 매 다음에 기다립니다.",
    ["1fe9ee6"] = "Marksmanship는 멀리서 쏩니다. 원거리 무기 DPS가 중요하고(같다면 Aimed Shot이 무기 한 번의 타격을 기반으로 하므로 느리고 한 방이 큰 쪽이 낫습니다) 민첩성. Careful Aim이 있으면 지능도 마나뿐 아니라 공격력으로 계산됩니다. 근접 무기는 능력치 때문에만 필요합니다.",
    ["184fc61"] = "Survival은 두 곳에서 싸웁니다. 원거리: 준비될 때마다 Multi-Shot(즉시 시전이고 Aimed Shot과 재사용 대기시간을 나누므로 Aimed Shot은 거의 쓰지 않습니다), 그리고 Serpent Sting, Arcane Shot, Auto Shot. 근접: Immolation Trap, 그다음 Raptor Strike(즉시, 재사용 6초)와 회피 후 Mongoose Bite. 전투 전에 Hunter's Mark, 소환수가 먼저 들어갑니다.",
    ["d85837a"] = "Strider Kick: 무기의 전체 피해를 주는 발차기로 3초 동안 30% 빨라집니다. 근접을 끝내고 다시 원거리로 돌아가는 버튼입니다. 근접에서는 먼저 Immolation Trap, 쓸 수 있으면 Mongoose Bite, Raptor Strike. 원거리에서는 준비되면 Multi-Shot, Serpent Sting, Arcane Shot, Auto Shot. 여러 몬스터에게는 함정 재사용 대기시간이 모두 같으므로 Explosive Trap이 Immolation Trap 자리를 차지합니다.",
    ["e7233e1"] = "Lacerating Strikes가 있으면 Mongoose Bite마다 타격 피해의 40%에 해당하는 출혈이 21초에 걸쳐 남습니다.",
    ["10bfe36"] = "Survival은 쏘기도 하지만 근접 무기로도 때립니다(Raptor Strike와 Strider Kick은 무기 피해 기반). 느린 양손 무기가 도움이 됩니다. 그다음 민첩성이 중요합니다. 49레벨부터 Careful Aim으로 지능이 공격력으로도 유용해집니다.",
    ["0718298"] = "Blink, Evocation, Mana Shield, Blizzard, Fire Ward, 두 수도로 순간이동 (그리고 Arcane과 Fire는 Arcane Blast)",
    ["ad986c1"] = "Conjure Mana Agate (첫 번째 마나 보석)",
    ["3e67dd9"] = "Ice Armor; 직업 퀘스트 (마법봉 Ice Fury)",
    ["3ddbf7c"] = "Frostfire Bolt, 첫 포털",
    ["3d9e7fb"] = "항상 Arcane Intellect와 방어 주문(지금은 Frost Armor)을 유지하세요. 마나를 쓰는 주문을 쓸 때마다 5초 동안 마나 회복이 멈추므로, 거의 죽은 몬스터에게는 풀 시전이 아깝습니다. 5레벨쯤에 마법봉을 구하세요(마법부여사가 Lesser Magic Wand를 만들어 주고 13레벨부터 Greater Magic Wand): 특성이 생기기 전에는 내 주문만큼 또는 그 이상 피해를 주면서 마나를 쓰지 않습니다.",
    ["2991425"] = "최대 사거리에서 Frostbolt로 시작하면 몬스터가 감속된 채로 옵니다. 다가오는 동안 계속 시전하고, 마무리는 Fire Blast, 남은 것은 마법봉으로.",
    ["5d6b9a7"] = "Frost Nova는 주위를 모두 얼립니다. 피해를 주면 깨지므로 뒤로 물러서며 계속 시전할 수 있습니다. 몬스터가 근접해 오면 Frost Nova 후 물러서세요.",
    ["11f2d67"] = "Missile Barrage와 함께: 멀리서 Frostbolt(Arcane과 Frost) 또는 Fireball(Fire)로 시작하고 계속 시전하다가 발동하면 Arcane Missiles를 쓰세요. 공짜 일제사격이 됩니다. Missile Barrage는 레벨업 중 마나를 가장 많이 아껴 주는 특성입니다.",
    ["b985201"] = "Evocation은 8초 동안 집중하여 마나를 크게 회복합니다. 달리는 동안 재사용 때마다 Blink를 쓰면 약 5분의 1 더 빨리 도착합니다. 귀환석은 퀘스트 지역에 쓰는 편이 좋습니다. 순간이동이 이미 수도로 데려다 주기 때문입니다.",
    ["a601e53"] = "Arcane Blast: 시전할 때마다 지능의 12%에 해당하는 주문 피해를 얻으며, 최대 4중첩이 18초 지속됩니다. 중첩마다 다음 시전의 비용이 100% 늘어납니다. 멀리서 Frostbolt, 그다음 Missile Barrage가 발동할 때까지 Arcane Blast를 한 번에서 세 번, 그리고 Arcane Missiles. 4중첩까지 가지 말고 중첩이 사라지게 두세요. Clear Casting은 중첩된 Arcane Blast에 쓰세요. 근접에서는 Frost Nova 후 물러서기. 마무리는 Fire Blast와 마법봉.",
    ["e55eb73"] = "Arcane Wrath: 재사용 6초의 무거운 타격(추가 피해는 최대 마나의 5%에 해당). 멀리서 Frostbolt, 그다음 Arcane Wrath, Missile Barrage까지 Arcane Blast 한 번에서 세 번, 그리고 Arcane Missiles. 다가오면 Frost Nova, 다시 Arcane Wrath, 처치는 Fire Blast와 마법봉. 중첩이 사라지게 두지 않으면 늘어나는 비용이 마나를 비웁니다. Clear Casting은 중첩된 Arcane Blast나 Arcane Wrath에만, 싼 주문에는 절대 쓰지 마세요.",
    ["65a5bf0"] = "Presence of Mind: 시전 시간이 10초 미만인 다음 주문이 즉시 시전됩니다.",
    ["c51b464"] = "Arcane Power: 15초 동안 피해 +30%, 대신 마나 +30%.",
    ["dfc4101"] = "멀리서 Pyroblast 또는 Frostbolt로 시작하고 Arcane Wrath. Missile Barrage까지 Arcane Blast 한 번에서 세 번, 그다음 미사일. 58레벨부터는 재사용 때마다 Fire Blast, Heating Up이 3중첩이면 Pyroblast.",
    ["9226a40"] = "모든 전문화에서 주문력이 먼저입니다. 주문이 주문력에 따라 크게 늘어나기 때문입니다. 지능은 마나와 약간의 치명타를 올리고, 정신력은 마시는 휴식을 줄여 주며, Arcane은 마나를 빨리 쓰기 때문에 특히 중요합니다.",
    ["ebbbb02"] = "멀리서 Fireball. Missile Barrage가 발동할 때까지 Arcane Blast 한두 번, 그다음 미사일. 재사용 때마다 Fire Blast. 체력이 적은 몬스터는 거리를 둘 필요가 없습니다. 몇 번 때리게 두고 15% 아래에서는 마법봉이 마무리합니다.",
    ["9e5f918"] = "Scorch는 몬스터가 붙어 있어도 빈틈을 채웁니다.",
    ["ab79a6b"] = "멀리서 Frostfire Bolt로 시작하고, Missile Barrage가 발동할 때까지 Arcane Blast 한두 번, 그리고 미사일. 재사용 때마다 Fire Blast, 빈틈은 Scorch, 마지막 15%는 마법봉.",
    ["bece8ec"] = "Pyroblast와 Heating Up: Fireball, Frostfire Bolt, Fire Blast, Scorch의 지속 피해가 아닌 치명타마다 다음 Pyroblast가 4분의 1 빨라지며 최대 3중첩이고, Fire Blast는 피해를 줄 때마다 중첩을 하나 더합니다. Heating Up이 3중첩이 되면 Pyroblast를 시전하세요.",
    ["196edb9"] = "모든 전문화에서 주문력이 먼저입니다. 지능은 마나와 약간의 치명타를 올리고, 정신력은 마시는 휴식을 줄여 줍니다.",
    ["38bc29a"] = "Frost는 Precision으로 시작합니다. 두 포인트로 같은 레벨 몬스터에 대한 적중 확률이 100%가 됩니다.",
    ["c690916"] = "Frostbite: 내 냉기 효과가 15% 확률로 대상을 5초 동안 얼립니다. Ice Lance(27레벨부터): 얼어붙은 대상에게 300% 더 큰 피해, 재사용 8초는 Fire Blast와 공유합니다.",
    ["1f1ed9a"] = "멀리서 Frostbolt, 몬스터가 오는 동안 계속 시전. Frostbite가 대상을 얼리면 바로 뒤에 Ice Lance를 붙인 Frostbolt. Ice Lance가 준비되지 않았으면 Cone of Cold. 근접에서는 Frost Nova 후 물러서고, 얼어붙은 몬스터에게 Frostbolt와 Ice Lance. Missile Barrage: 미사일을 쓰거나, 이 몬스터가 거의 죽었으면 다음 몬스터를 위해 아껴 두세요. 얼지 않은 체력 낮은 몬스터에게는 Fire Blast나 마법봉.",
    ["2e43c7c"] = "Fingers of Frost가 있으면 다음 두 주문이 대상을 얼어붙은 것으로 취급합니다. 첫째는 Frostbolt, 둘째는 Ice Lance가 붙은 Frostbolt(Ice Lance가 아직 없으면 Cone of Cold). 강점은 30대에 있습니다. Shatter 이후 얼어붙은 대상은 가장 센 타격을 받습니다.",
    ["cecd125"] = "먼저 Ice Barrier, 1분이 지나면 다시 시전하세요. 보호막 외에 1분 동안 냉기 피해를 15% 늘려 줍니다.",
    ["959453a"] = "Winter's Chill: Frostbolt와 Ice Lance가 대상에게 최대 5번 중첩하며, 다음 Cone of Cold는 중첩마다 20% 더 강합니다.",
    ["5a9d3eb"] = "Redemption (직업 퀘스트)",
    ["3d343ad"] = "Seal of Command (Retribution 특성), Seal of Justice",
    ["32b558d"] = "이중 전문화와 탈것",
    ["38d0905"] = "전투 전에 Blessing of Might와 Devotion Aura. 그다음 세 단계: Seal of Righteousness, 몬스터에게 달려가며 Judgment, Holy Strike. 이후 Judgment와 Holy Strike는 준비될 때마다, 문장은 끝나기 직전에만 갱신하세요(Judgment가 문장을 더 이상 소모하지 않고 전역 재사용 대기시간 밖입니다). 마나는 치유 수단이기도 합니다. 다음 타격이 몬스터를 죽인다면 버튼을 건너뛰세요. 전투가 끝났을 때 마나가 남으면 Holy Light로 체력으로 바꾸세요. 위험하면 먼저 자신에게 Divine Protection, 그다음 치유.",
    ["f580de7"] = "Consecration은 여러 적과 싸우거나 마나가 남을 때: Judgment와 Holy Strike를 합친 것보다 비싸고 모든 피해를 주는 데 8초가 걸립니다. 모든 언데드와 악마에게는 30미터에서도 Exorcism.",
    ["2ea2c89"] = "Hammer of Wrath를 더하세요. 체력 20% 미만의 적을 마무리합니다.",
    ["c8d4778"] = "Retribution과 Protection은 같은 트리에서 거의 같은 특성으로 시작합니다. Deflection(막기 5%) 대신 Benediction을 고를 수 있습니다. 모든 즉시 기술의 마나 비용이 10% 줄고 Consecration을 감당하기 쉬워집니다.",
    ["a81d5b1"] = "Seal of Command와 함께: Blessing of Kings 또는 Might와 Retribution Aura. 오래 사는 몬스터에게는 먼저 Seal of the Crusader의 Judgment(몬스터가 신성 피해를 더 받음), 그다음 느린 무기라면 Seal of Command로 바꾸세요. 빠른 무기나 주문 피해가 많으면 Seal of Righteousness가 낫습니다. 이후 재사용 때마다 Judgment와 Holy Strike. 요령: Seal of Command의 Judgment는 기절한 대상에게 거의 두 배라서 Hammer of Justice로 시작한 뒤 Judgment.",
    ["733e5e6"] = "Sacred Arbiter: Holy Strike가 20% 더 강하게 때리고 대상에 걸린 모든 Judgment를 갱신합니다. 다른 성기사의 것도 포함입니다.",
    ["a01f90a"] = "Champion of the Light는 지능의 최대 60%를 주문 피해로 바꿉니다. 주문력이 붙은 장비가 더 좋아집니다. 40레벨의 Unsealed Wrath: 타격이 활성 문장의 복사본(최대 3개)을 보존하고, 문장을 바꾸는 것이 다시 이득이 됩니다.",
    ["5f3698b"] = "무기가 가장 중요합니다. 이상적으로는 주문력과 큰 피해가 있는 것. Seal of Command와는 느리고 무거운 무기가 최고입니다(Holy Strike와 문장의 피해가 늘어남). 나머지는 먼저 힘이나 공격력, 그다음 체력, 그다음 주문력.",
    ["4c063de"] = "Holy는 Retribution처럼 시작합니다. 처음 12포인트(21레벨까지)는 마나 효율과 Pursuit of Justice를 위해 Retribution에 넣습니다. 20레벨까지 치유는 Holy Light, Lay on Hands, Blessing of Protection입니다. 혼자 퀘스트할 때는 마나를 낭비하지 말고 딜러 성기사처럼 Seal of Righteousness, Judgment, Holy Strike를 쓰세요.",
    ["e1a4083"] = "Flash of Light로 치유가 두 가지가 됩니다. Holy Light는 느리고 강해서 생명력이 많이 필요하고 시간이 있을 때, Flash of Light는 빠르고 마나가 덜 들어 작고 꾸준한 피해에 씁니다. 알맞은 치유를 고르는 것이 일의 전부입니다. 잘못 고르면 마나만 태웁니다. 20레벨부터 Consecration, Exorcism, Blessing of Kings도 얻습니다.",
    ["42143bb"] = "22레벨부터 포인트는 Holy에 들어갑니다. Spiritual Focus(맞아도 시전이 덜 밀립니다), 그다음 Reverence(시전 중에도 마나 재생의 일부가 계속됩니다)와 Healing Light(Holy Light, Flash of Light, Holy Shock의 치유량 증가)입니다.",
    ["a1c4391"] = "치유 방법: 탱커가 꾸준히 피해를 받으면 Flash of Light나 Holy Light, 갑작스러운 피해에는 Holy Shock, 위급할 때는 Lay on Hands(마나를 전부 씁니다)를 쓰세요. Blessing of Protection은 물리 피해를 받는 아군에게 쓰고 탱커에게는 쓰지 마세요. 면역이 되면 적이 다른 사람에게 향합니다.",
    ["e98c82f"] = "Illumination: Flash of Light, Holy Light, Holy Shock의 치명타 치유가 마나(기본 비용의 절반)를 돌려줄 수 있어서 지능과 치명타가 중요합니다. 37레벨부터 주 대상에게 Oath of Light, 38레벨부터 Infusion of Light: Holy Shock나 Flash of Light의 치명타 치유가 다음 Holy Light를 더 빠르게 만듭니다.",
    ["3bb92dd"] = "40레벨에 이중 전문화(혼자 퀘스트할 때를 위해 Retribution을 두 번째 전문화로 두세요)와 판금 갑옷을 얻습니다. 42레벨부터 Holy Shock: 재사용 대기시간 10초의 즉시 치유, 또는 적에게 신성 피해를 줍니다. 45레벨부터 Divine Favor: 다음 치유가 항상 치명타입니다(재사용 대기시간 2분). 탱커가 위험할 때 쓰세요. 47레벨부터 Holy Power가 Holy Shock와 Holy Strike의 치명타 확률을 높입니다.",
    ["31364c3"] = "Light's Vigil: 아군에게 30초 동안 걸리는 효과로, 같은 대상에게 Holy Shock를 쓰면 발동해 파티도 치유하고 Holy Shock의 재사용 대기시간이 시작되지 않습니다. 마나 소모가 크고 파티당 하나만 가능하니 여러 명이 피해를 입을 때 아껴 두세요. 적에게 쓰면 마나의 75%를 돌려줍니다. 마지막 포인트(56레벨부터)는 Divine Intellect에 넣습니다.",
    ["7fda0df"] = "Holy는 치유력이 가장 먼저, 그다음 지능(마나와 치명타 증가, Illumination으로 마나 회복), 그다음 5초당 마나와 정신력(Reverence로 시전 중에도 재생의 일부가 계속됩니다)입니다. 무기는 피해가 아니라 능력치를 봅니다. 치유력과 정신력이 붙은 철퇴가 DPS 높은 무기보다 낫습니다. 40레벨까지는 사슬, 그 뒤로는 판금이지만 알맞은 능력치가 붙은 천 장비가 능력치 없는 사슬 장비보다 낫습니다.",
    ["a531e3f"] = "Seal of Fury는 탱커의 문장입니다. 타격마다 추가 신성 피해를 주고 방패와 함께하면 그 피해의 절반만큼 흡수량을 얻습니다. 그 Judgment는 10미터에서 3초 동안 도발하게 합니다. Righteous Fury는 모든 위협을 33% 늘립니다. 22레벨부터 Pursuit of Justice 이후 Protection 트리로 넘어갑니다.",
    ["8279baa"] = "Blessing of Kings, Retribution Aura, Righteous Fury 활성. 항상 Seal of Fury를 유지하세요. 몬스터에게 달려가며 Judgment로 도발하세요. 마나가 허락하면 근접하자마자 Consecration을 깔고, 이후 재사용 때마다 Holy Strike, 언데드와 악마에게는 Exorcism. 최대 네 마리까지 모아 Consecration으로 모두 태우세요.",
    ["34e2900"] = "Shield Specialization: 막기 한 번이 최대 마나의 4%를 돌려주며 3초에 한 번까지입니다. 마나의 큰 부분입니다.",
    ["cc3ac76"] = "Templar's Bulwark: 8초 동안 체력 전체만큼의 피해를 흡수하는 보호막이지만 1분 동안 Forbearance가 걸립니다. 37레벨부터 Swift Judgement: 문장의 Judgment가 재사용 1분으로 저절로 발동하므로 두 번째 도발이 생깁니다.",
    ["be55413"] = "Holy Shield: 10초 동안 더 자주 막고 최대 4번의 막기가 신성 피해를 줍니다. Reckoning(43레벨부터)은 막기나 치명타를 받은 뒤 추가 공격을 줄 수 있습니다.",
    ["e76d8e9"] = "Protection은 주문력이 먼저입니다(Seal of Fury, Holy Shield, Consecration은 신성 피해). 그다음 힘과 체력. 무기는 더 빠른 쪽이 낫습니다. Seal of Fury는 타격마다 발동하기 때문입니다. 주문력이 붙은 무기는 피해가 조금 낮아도 괜찮습니다.",
    ["05e5db7"] = "Shadow Word: Pain; 짧은 직업 퀘스트 (로브)",
    ["c95888a"] = "Mind Blast, Resurrection; 종족 퀘스트가 내 종족만의 첫 기술을 가르쳐 줍니다",
    ["091c0cd"] = "Holy Fire, Flash Heal, Devouring Plague, Fear Ward, Mind Soothe, Shackle Undead; 두 번째 종족 기술",
    ["71b2a72"] = "전투 전에 자신에게 Fortitude. Smite로 시작하고 대상에게 Shadow Word: Pain을 건 뒤 마법봉으로 마무리하세요. 마법봉은 마나가 들지 않고 초반 피해의 큰 부분을 담당합니다(사용하기 전에 0.5초 가만히 서세요). 몬스터가 닿으면 먼저 Power Word: Shield. 가장 중요한 것은 좋은 마법봉입니다. 더 좋은 것을 찾을 때마다 바꾸세요.",
    ["e023128"] = "Mind Blast는 재사용이 짧은 강한 타격입니다. 처음 일곱 특성 포인트는 모든 전문화가 같습니다: Wand Specialization(10-11)과 Spirit Tap(12-16). Spirit Tap은 경험치를 주는 몬스터를 처치할 때마다 15초 동안 정신력을 두 배로 하고, 그동안 시전 중에도 마나 회복의 절반이 계속됩니다. 마시는 휴식이 줄어듭니다.",
    ["8df287d"] = "Inner Fire: 방어력이 늘고 받는 타격마다 충전을 하나 씁니다. Fortitude와 함께 항상 자신에게 유지하고 끝나면 다시 거세요.",
    ["bebe913"] = "Psychic Scream은 주변 적을 도망가게 하지만 조심하세요. 다른 몬스터를 끌고 돌아올 수 있습니다.",
    ["ffa87bf"] = "오늘 스승은 다른 어느 레벨보다 많은 것을 가르쳐 줍니다: Holy Fire(느리지만 강한 시작이고 지속 피해도 줌), Flash Heal(빠르지만 비쌈), Devouring Plague(지속 피해이면서 나를 치유함) 등.",
    ["084f80e"] = "Shadow는 혼자 레벨업할 때 권장하는 전문화입니다. 포인트가 Shadow Word: Pain, Mind Blast, Mind Flay로 가서 몬스터가 더 빨리 죽습니다.",
    ["f33a503"] = "몬스터가 닿으면 자신에게 Shield. Mind Blast로 시작하고 Shadow Word: Pain. 27레벨부터 Devouring Plague와 Mind Flay도, Shadow Word: Pain 뒤에 Vampiric Embrace를 더해 암흑 피해로 치유받으세요. 그다음 마법봉으로 마무리. 마나가 낮으면 Devouring Plague와 Mind Flay는 건너뛰세요.",
    ["496ef3d"] = "Shadow Word: Death는 갑작스러운 피해이지만 대상이 살아남으면 최대 체력의 30%를 내가 받습니다. 마지막 일격을 위해 아껴 두세요.",
    ["edd0d02"] = "Shadowform: 싸우는 동안 Shadowform을 유지하세요(암흑 피해 +10%, 암흑 주문 마나 절반, 물리 피해 -15%, 하지만 치유 주문은 쓸 수 없으니 치유 전에 나오세요). Mind Blast로 시작하고 Shadow Word: Pain, Vampiric Embrace, Devouring Plague, Mind Flay. 한 번 더 때려 몬스터가 죽으면 Shadow Word: Death, 아니면 마지막은 마법봉에 맡기세요. 몬스터가 닿으면 자신에게 Shield.",
    ["b912dce"] = "Shadow는 주문력이 먼저입니다(암흑 주문력도 좋습니다. 피해 거의 전부가 암흑입니다). 그다음 치명타와 적중. 마법봉이 매우 중요합니다. 초반에는 피해의 큰 부분을 담당합니다.",
    ["8e3f775"] = "Discipline은 혼자 플레이할 때 권장하는 치유 전문화입니다. 20레벨부터 Power in Light가 Smite에 피해를 더합니다.",
    ["916c9c2"] = "멀리서 Holy Fire로 시작하고, 몬스터가 오는 동안 Smite, 그다음 Mind Blast, Shadow Word: Pain, 마법봉. 싸움이 나쁘게 흐르면 자신에게 Shield 후 치유: 급하면 Flash Heal, 시간이 있으면 Heal.",
    ["a80f7e5"] = "Penance: 적을 해치거나 아군을 치유하는 신성 타격의 연속이며 재사용 12초, 첫 타격은 즉시 나갑니다.",
    ["037a666"] = "먼저 자신에게 Shield. 멀리서 Holy Fire로 시작. 몬스터가 걸어오는 동안 Smite, 그다음 같은 대상에 Penance(Power in Light가 더 세게 때리게 함). 이어서 Mind Blast와 Shadow Word: Pain. 마무리는 한 방에 죽으면 Shadow Word: Death, 아니면 마법봉. Weakened Soul이 사라질 때마다 다시 보호할 수 있습니다.",
    ["9d0affc"] = "Power Infusion: 15초 동안 피해와 치유 +20%, 자신이나 친구에게. 준비될 때마다 시작 직전에 자신에게 거세요. 60레벨의 Inner Focus는 위급할 때: 다음 주문이 무료입니다.",
    ["8e7cd8d"] = "Discipline과 Holy는 치유량과 마나 회복을 찾고, 그다음 지능과 정신력. 같은 능력치를 가진 무기를 고르세요. 지팡이든 보조 손이 있는 한손이든 상관없습니다.",
    ["c5c1351"] = "전투 전에 자신에게 Shield와 Renew. 그다음 Holy Fire로 시작하고, 몬스터가 오는 동안 Smite, Mind Blast, Shadow Word: Pain. 죽일 수 있으면 Shadow Word: Death, 아니면 마법봉으로 마무리.",
    ["575bdd0"] = "Holy Nova는 주변의 모든 적에게 피해를 주고 파티를 치유합니다. 마나가 많이 들므로 여러 적이 붙었을 때나 무료일 때 쓰세요(43레벨의 Searing Light: Holy Fire가 다음 Holy Nova를 무료로 만들 수 있음).",
    ["6953353"] = "전투 전에 자신에게 Shield, Renew, Prayer of Mending(대상이 다음에 피해를 입을 때 치유하고 파티의 다른 사람에게 튕김, 재사용 10초).",
    ["a5c9096"] = "Holy는 치유량과 마나 회복을 찾고, 그다음 지능과 정신력. 같은 능력치를 가진 무기를 고르세요.",
    ["aa71e89"] = "Backstab (단검 필요, 등 뒤에서만), Pick Pocket",
    ["2e3c463"] = "Slice and Dice, Sprint, Sap; 직업 퀘스트 (Blade of Cunning)",
    ["3a2246d"] = "Ambush (단검 필요), Poised (패시브)",
    ["8abd601"] = "Rupture; 독 퀘스트: Instant Poison과 Crippling Poison",
    ["6c840ea"] = "Shank (Forever의 새 기술)",
    ["f3d428e"] = "Mutilate (Assassination 특성)",
    ["3e307c7"] = "Death Mark (Subtlety 특성), Slice and Dice 2등급",
    ["f14c847"] = "Shank 2등급",
    ["a554ba3"] = "몬스터에게 걸어가 연계 점수가 있는 동안 Sinister Strike, 그다음 Eviscerate: 점수가 많을수록 강한 타격. Stealth는 지금은 단축바에 두어도 됩니다. 싸움이 나빠지면 Evasion과 Gouge로 시전을 끊거나 몇 초를 벌어 보세요.",
    ["44b2b7e"] = "Slice and Dice(마무리 기술: 공격 속도 20% 증가, 점수가 많을수록 오래 지속), Sprint(15초 동안 50% 빠르며 Stealth가 풀리지 않음), 시작 전 인간형을 전투에서 빼는 Sap.",
    ["665b56f"] = "Rupture: 점수가 많을수록 긴 출혈. 독 퀘스트와 함께 Instant Poison과 Crippling Poison.",
    ["d06b2e0"] = "Shank: 빗나가지 않는 보조 손 타격. 1등급은 기력 5를 쓰고 15를 돌려주며 10초에 재충전. 26레벨부터 은신에서 Cheap Shot: 4초 기절에 점수 2개.",
    ["6974c7f"] = "Combat은 결투가입니다. 원하는 무기로 근접 전투를 하고 어떤 무기와도 맞으며 시작할 때 은신이 필요 없습니다. 혼자 레벨업할 때 권장하는 전문화입니다.",
    ["cea5a19"] = "Riposte: 내가 막기에 성공한 뒤 불이 들어오며 무기 피해의 1.5배로 때리고 몬스터를 6초 동안 무장 해제시키며 기력 10만 들고 재사용 6초.",
    ["5288c4d"] = "양쪽 무기에 Instant Poison. 힘든 싸움에는 은신에서 Cheap Shot, 아니면 바로 Sinister Strike. 막기 직후 Riposte. Shank 재사용 중에는 Sinister Strike로 점수를: 처음 다섯 점수는 Slice and Dice에, 다음 다섯은 Eviscerate에.",
    ["869d1bf"] = "몬스터 둘이 붙었을 때: Blade Flurry(2분마다, 15초 동안 공격 속도 20% 증가하고 타격마다 근처의 두 번째 적도 맞춤).",
    ["9fb5eb8"] = "위험한 몬스터에게 Adrenaline Rush(5분마다, 15초 동안 기력이 두 배 빨리 회복).",
    ["f8cc28b"] = "큰 Eviscerate 직전에 Cold Blood.",
    ["625324b"] = "민첩성이 붙은 가죽 방어구가 원하는 것입니다. 적중, 치명타, 공격력, 체력이 유용합니다. Combat은 모든 종류의 무기를 쓸 수 있습니다. Hack and Slash가 각각 보너스를 주기 때문입니다: 검과 도끼, 단검과 주먹 무기, 둔기.",
    ["d01cb25"] = "Assassination은 독 전문가입니다. 독과 마무리 기술이 점점 강해지고 40레벨에 Mutilate가 옵니다.",
    ["9eb3d72"] = "양쪽 무기에 Instant Poison. 은신에서 Garrote 또는 Cheap Shot으로 시작. 점수를 위해 Sinister Strike, Shank는 재사용 때마다. Slice and Dice, 그다음 Eviscerate. 큰 Eviscerate를 위해 Cold Blood를 아껴 두세요.",
    ["33aceb3"] = "Venom: Shank 뒤 6초 동안 독이 30% 더 강하고 20% 더 자주 발동합니다. Shank는 재사용 때마다.",
    ["88ede56"] = "Mutilate가 점수를 쌓습니다. 양쪽 무기로 때리고 중독된 대상에게 20% 더 강하며 점수 2개를 줍니다. 단검 두 자루가 필요합니다. Slice and Dice, Venom을 위해 Shank는 재사용 때마다, 그다음 Eviscerate. 큰 Eviscerate에는 Cold Blood.",
    ["20500ff"] = "민첩성이 붙은 가죽 방어구. Assassination은 Backstab, Ambush, Mutilate에 단검이 필요합니다. 적중, 치명타, 공격력, 체력이 유용합니다.",
    ["5259278"] = "Subtlety는 매복가입니다. 단검을 들고 어둠 속에서 모든 싸움을 시작합니다.",
    ["64f4a07"] = "주무기에 단검, 양쪽 무기에 Instant Poison. 몬스터 등 뒤로 다가가 Premeditation, 그다음 Ambush, Ghostly Strike, Garrote. 나머지는 Sinister Strike로 쌓고, 기력을 위해 Shank는 재사용 때마다, 마무리는 Eviscerate.",
    ["37c1365"] = "Hemorrhage가 Sinister Strike 대신 점수를 쌓습니다.",
    ["c0f22d5"] = "Hemorrhage와 Shank가 점수를 쌓고 Boot Knife가 있으면 Shank 하나가 둘로 계산됩니다. Death Mark는 6초 동안 피해를 저장합니다. 몬스터가 충분히 오래 살 때 점수 한 세트를 쓰고 Eviscerate로 마무리하세요. 싸움이 나빠지면 Preparation이 Premeditation, Ghostly Strike 및 다른 재사용 대기시간을 초기화합니다.",
    ["a993dd2"] = "민첩성이 붙은 가죽 방어구. Subtlety는 주무기에 단검을 듭니다(Ambush와 Backstab이 요구). 적중, 치명타, 공격력, 체력이 유용합니다.",
    ["abbb551"] = "Earth Shock; 대지 토템 퀘스트: Stoneskin Totem",
    ["8e8845b"] = "불 토템 퀘스트: Searing Totem",
    ["2be8a5e"] = "Ghost Wolf, Frost Shock, Lesser Healing Wave, Frostbrand Weapon, Healing Stream Totem (물 토템 퀘스트), Call of the Elements, Totemic Recall",
    ["0a8c77d"] = "Windfury Weapon, Reincarnation (Ankh 필요), Astral Recall, Grounding Totem",
    ["47fd721"] = "Chain Lightning, Windfury Totem; 바람 토템 퀘스트 (폭풍의 무기)",
    ["b821239"] = "Chain Heal, 사슬 갑옷",
    ["d6b5209"] = "Rockbiter Weapon은 무기에 유지하고 8레벨부터는 전투 전에 Lightning Shield를 두릅니다. Lightning Bolt로 시작하고 도착하면 즉시 시전인 Earth Shock. 시전자에게는 충격 기술을 아껴 두었다가 시전을 끊으세요. 몬스터가 붙으면 근접 타격이 마무리합니다. 다른 몬스터가 오면 Earthbind Totem을 놓으세요. 감속시키고 카이팅할 수 있게 해 줍니다. 전투가 끝나고 다쳤으면 Healing Wave.",
    ["fa734a3"] = "전문화마다 역할이 분명합니다. Enhancement는 큰 무기, 토템, 충격 기술로 근접 전투를 하고, Elemental은 Lightning Bolt, Chain Lightning, Fire Nova로 원거리에서, Restoration은 치유를 하며 파티나 던전에서 함께하고 혼자 퀘스트를 하지는 않습니다. 마나가 떨어지면 Enhancement는 계속 때립니다(처치가 더 오래 걸림). Elemental은 더 힘들어집니다.",
    ["b74be3c"] = "Flame Shock는 즉시 화염 피해를 주고 12초 동안 탑니다. Flametongue Weapon은 타격마다 화염 피해를 더하고, Searing Totem은 근처의 적을 쏘는 작은 포탑입니다.",
    ["35c7293"] = "Enhancement는 퀘스트에 권장하는 전문화입니다. 약점도 있습니다. 나쁜 무기는 피해를 크게 낮추고, 초반 마나 비용이 부담되며, 여러 적을 한꺼번에 상대하기 어렵습니다.",
    ["028a6b7"] = "Stormstrike는 8초마다 무기의 전체 피해로 즉시 때리고, 대상은 다음 Lightning Bolt, Chain Lightning, Earth Shock에서 20% 더 받습니다.",
    ["a94041d"] = "Stormstrike는 준비될 때마다, 바로 뒤에 Earth Shock(Stormstrike 타격이 충격 기술을 강하게 함). Rockbiter Weapon은 항상 무기에, Lightning Shield는 자신에게. 전투 전에 Strength of Earth와 Mana Spring, 마나가 허락하면 Searing Totem 또는 Magma Totem. Lightning Bolt 1등급(가장 싼 것)으로 시작하고 나머지는 일반 타격. Fire Nova는 몬스터가 내 불 토템 범위에 있고 마나가 남았을 때만. 처치 후 Healing Wave, 마나가 낮으면 마시세요.",
    ["18a8896"] = "Rockbiter 대신 무기에 Windfury Weapon: 타격마다 20% 확률로 추가 공격 둘을 줍니다. Enhancement의 핵심입니다. 회피나 막기로 Stormstrike가 초기화되면 즉시 다시 누르세요. Windfury Totem, 시전자에게는 그 자리에 Grounding Totem.",
    ["f3777c4"] = "Maelstrom Weapon: 타격이 최대 5충전까지 쌓이고 충전마다 다음 Lightning Bolt가 더 빠르고 싸집니다. 5충전이면 가장 높은 등급의 Lightning Bolt를 쓰세요. 46레벨부터 Water Shield가 Lightning Shield 자리를 대신합니다(하나만 가질 수 있음).",
    ["022a55d"] = "Enhancement는 무기가 무엇보다 중요합니다. 이상적인 것은 속도 3.3에서 3.8 사이의 느린 양손 무기입니다. 그다음 힘과 공격력, 바로 뒤에 지능. Mental Dexterity와 마나를 키워 주기 때문입니다.",
    ["4540d89"] = "Earthbound: Earthbind Totem을 놓으면 근처의 적이 5초 동안 묶입니다.",
    ["bcd1d77"] = "전투 전에 Mana Spring Totem과 불 토템(한 마리면 Searing, 여러 마리면 Magma), 자신에게 Lightning Shield. 사거리 끝에서 Lightning Bolt로 시작하고 대상에게 Flame Shock를 건 뒤 Lightning Bolt를 계속. 몬스터가 셋 이상이면 준비될 때마다 Fire Nova. Earth Shock는 시전자를 끊고 내 쪽으로 오게 합니다. 몬스터가 다가오면 Earthbind Totem. 끝나면 치유하고 마시세요.",
    ["13a3832"] = "몬스터 하나일 때: Searing Totem, 멀리서 Lightning Bolt로 시작, Flame Shock, 계속 Lightning Bolt. 셋 이상일 때: Magma Totem, Chain Lightning으로 시작, 그중 하나에 Flame Shock, 이후 재사용 때마다 Chain Lightning과 Fire Nova, 그 사이에 Lightning Bolt.",
    ["2c3ba7a"] = "Lightning Mastery(15초 지속, 재사용 3분): 15초 동안 Lightning Bolt가 더 빨리 시전되고 Chain Lightning이 재사용 대기시간을 무시합니다. 정예나 큰 무리에 쓰고, 아니면 재사용 때마다.",
    ["b56c9ed"] = "Water Shield가 자신의 Lightning Shield 자리를 대신합니다.",
    ["4688073"] = "Elemental은 주문력을 찾고, 지능은 주로 마나 때문입니다. 40레벨부터 사슬 갑옷을 입을 수 있습니다.",
    ["b4ca62b"] = "전투 전에 Water Shield, Mana Spring Totem, 그리고 파티가 쓸 수 있는 토템. 누군가 피해를 입는 동안 Healing Wave가 주력입니다. Lesser Healing Wave는 1.5초에 시전하고 마나 대비 치유량이 적습니다. 시간이 중요한 순간을 위해 아껴 두세요. 파티 전체의 마나가 바닥나면 Mana Tide Totem(12초, 재사용 5분). 위험한 사람이 없으면 피해를 더하세요: 대상에게 Lightning Bolt, 무리에게 Fire Nova. 끝나면 마시세요.",
    ["42937c0"] = "Nature's Swiftness(3분마다): 다음 자연 주문이 즉시 시전되므로 곧 죽을 친구에게 즉시 Healing Wave. 근접 플레이어가 있으면 Windfury Totem.",
    ["9b2d19c"] = "Riptide: 재사용 12초의 지속 치유이며, Riptide 대상에게 바로 시전한 Chain Heal은 25% 더 강합니다. Chain Heal은 대상과 다른 아군 둘을 치유하므로 파티에 흩어진 피해를 감당합니다.",
    ["a86408d"] = "Restoration은 치유량을 찾고, 지능은 주로 마나 때문입니다. 40레벨부터 사슬 갑옷을 입을 수 있습니다.",
    ["c86a1be"] = "Voidwalker (직업 퀘스트), Drain Soul, Healthstone",
    ["40cb6b4"] = "Succubus와 Incubus (직업 퀘스트), Demon Armor, Curse of the Elements, Rain of Fire, Ritual of Summoning",
    ["df7bfa2"] = "Felhunter (직업 퀘스트), Hellfire",
    ["19e5308"] = "Howl of Terror, Felsteed (퀘스트)",
    ["1c5b068"] = "악마가 먼저 들어가고 그다음 Bane of Agony와 Corruption. 가장 강한 몬스터에게만 Immolate를 겁니다. 악마가 붙잡고 있기 때문입니다. 피해가 주의를 끌기 때문에 순서가 중요합니다. Agony의 처음 틱은 작아서, 새 Immolate가 몬스터를 나에게 돌아서게 할 만큼 강하게 때릴 때까지 악마가 붙잡아 둡니다. Demon Skin을 유지하고, 거의 죽은 몬스터에게는 DOT를 건너뛰며, 아직 피해를 주는 동안 Agony를 갱신하지 마세요. 마법봉이 생기기 전에는 Shadow Bolt로 마무리하고, 그다음에는 마법봉을 구하세요. 한 발마다 다음 전투를 위한 마나가 절약됩니다.",
    ["ea42414"] = "Drain Soul은 Soul Shard의 주 공급원입니다. 시시하지 않은 몬스터가 그 흡수로 죽으면 항상 하나를 줍니다. 조각이 적으면 처치를 그것으로 마무리하세요. Healthstone, Soul Stone, Voidwalker·Succubus·Felhunter 소환에는 조각이 필요합니다.",
    ["72f97d5"] = "Drain Life는 화면을 보는 방식을 바꿉니다. 파란 막대가 낮고 체력이 괜찮으면 Life Tap, 체력이 정말 떨어졌으면 몬스터에게 Drain Life. 그러면 거의 모든 쉬는 시간이 사라집니다.",
    ["51205f3"] = "Demon Skin 대신 Demon Armor. Ritual of Summoning으로 나와 동료 둘이 아직 멀리 있는 파티원을 데려옵니다. Fear는 붕대를 감을 몇 초의 여유를 줍니다.",
    ["9d83c05"] = "혼자 플레이한다면 Affliction이 정답입니다. 정확도와 즉시 시전 Corruption이 일찍 옵니다. Curse of the Elements는 Agony 옆에 둡니다. 25레벨부터 Nightfall은 Corruption, Drain Life, Drain Soul의 피해로 발동할 수 있고, 발동 후 Shadow Bolt는 시전 시간이 없습니다. 흡수 특성을 30레벨 조금 전에 얻어 모든 전투에서 Drain Life에 기댈 수 있습니다.",
    ["04f03c2"] = "Siphon Life: 30초 동안 3초마다 틱이 있으므로 10초 만에 죽는 몬스터는 3분의 1만 받습니다. 긴 전투를 위해 아껴 두세요.",
    ["703c37f"] = "Demonic Sacrifice: Felhunter를 희생하면 두 시간 동안 4초마다 전체 체력의 3%를 회복합니다. 악마를 소환하면 취소되므로 여기서부터는 소환수 없이 퀘스트를 합니다.",
    ["2dbcea6"] = "Wrack: 6초 동안 집중하며 암흑 피해를 주고, 지속되는 동안 그 대상에 걸린 다른 암흑 DOT가 10% 더 강하게 때립니다.",
    ["edb7e47"] = "주문력이 붙은 무기를 고르세요. 때리는 데는 거의 쓰지 않을 것이기 때문입니다. 초반에는 마법봉 개선이 거의 모든 다른 것을 이기고, 이후에는 주문력이 먼저입니다. 체력은 Life Tap으로 마나로 바꿀 여분의 생명이고, 지능은 더 큰 마나 통, 정신력은 Life Tap마다 더 많은 것을 줍니다.",
    ["1c3a6a3"] = "악마가 일하는 것을 보는 쪽이 좋다면 Demonology: 25레벨부터 Demonic Brand와 함께. 25레벨부터 Searing Pain이 대상에 10초 동안 표식을 남기고, 악마의 처음 여섯 번의 타격까지 추가 피해를 줍니다. 악마가 싸우는 대상에게 빠른 Searing Pain으로 갱신하고 빈틈은 DOT와 마법봉으로 메우세요.",
    ["00d4a86"] = "Soul Link: 나에게 향한 직접 타격의 30%가 악마에게 가고, 둘 다 피해가 3% 늘어납니다. 악마를 바꾸면 사라지므로 그때마다 다시 거세요.",
    ["a3cee7a"] = "Demonic Pact: 희생은 악마를 바꿔도 유지됩니다. 희생한 바로 그 악마를 다시 소환하지 않는 한 그렇습니다. 던전에서는 Imp를 희생하고(암흑 피해 15% 증가), 혼자 하는 퀘스트에서는 치유 때문에 Felhunter를 희생하고 Voidwalker, Succubus, Incubus와 함께 싸우세요. 27레벨부터 Affliction으로 레벨업하다가 전문화를 바꿀 수도 있습니다. Demonic Brand 세 등급에 필요한 포인트가 있습니다.",
    ["545f2c9"] = "Destruction은 10레벨부터 플레이할 수 있지만 39와 40레벨에 훨씬 강해지고 다른 둘보다 시전하며 가만히 서 있는 시간이 깁니다. 나중에 골라도 됩니다.",
    ["0b5d29c"] = "Shadowburn: Shard 하나를 쓰는 즉시 타격이며 시시하지 않은 대상이 8초 안에 죽으면 돌려줍니다.",
    ["124afde"] = "시작이 달라집니다. 최대 사거리에서 Shadow Bolt, 볼트가 날아가는 동안 Immolate. 그러면 몬스터가 악마가 아닌 나에게 오므로 빨리 끝낼 수 있는 싸움을 고르세요. Shadowburn이 몬스터를 마무리합니다. Conflagrate는 Immolate가 끝날 때를 위해 아끼는 편이 좋습니다.",
    ["07ea333"] = "Shadow and Flame이 있으면 Conflagrate가 암흑 피해를 20%, Shadowburn이 화염 피해를 20% 올립니다. Conflagrate는 더 이상 Immolate를 소모하지 않고 Shadowburn은 항상 Shard를 돌려줍니다. 39레벨부터는 아낄 이유가 없습니다.",
    ["609f38c"] = "Incinerate는 내 Immolate로 이미 타고 있는 모든 것에 25% 더 큰 피해를 줍니다.",
    ["a1d5005"] = "Defensive Stance, Taunt, Sunder Armor (직업 퀘스트), Bloodrage",
    ["b87bfb2"] = "Revenge, Demoralizing Shout, Tactical Mastery (스승에게서 배움)",
    ["a61955b"] = "Victory Rush, Cleave, Slam, Retaliation; 무기 두 자루를 쓸 수 있습니다",
    ["323f468"] = "Berserker Stance, Berserker Rage, Intercept (직업 퀘스트)",
    ["b289adb"] = "판금 갑옷과 탈것",
    ["2debde0"] = "전투 전에 Battle Shout, Charge, 오래 사는 몬스터에게 Rend, 그다음 일반 타격이 분노를 쌓게 두세요. Heroic Strike는 필요 없는 분노가 있을 때만. 일반 타격을 대신하고 그 타격은 분노를 주지 않습니다. 여러 몬스터에게는 Thunder Clap. 곧 죽을 몬스터에게 분노를 쓰지 마세요.",
    ["f98c5d6"] = "전투 사이에 Bloodrage: 체력을 조금 쓰고 분노 10을 즉시, 10초 뒤 10을 더 줍니다. 분노 없이 전투를 시작하지 마세요.",
    ["970305a"] = "불이 들어올 때마다 Victory Rush: 경험치를 주는 처치 후 20초 동안 쓸 수 있고 피해를 주며 체력 10%를 회복하고 재사용 30초에 분노를 쓰지 않습니다.",
    ["a60b4a3"] = "14레벨부터 Revenge가 주 공격입니다. 불이 들어올 때마다(막기, 회피, 막아내기 뒤) 쓰세요. 방패와 한손 무기로 바꾸세요. 무리에게는 Thunder Clap과 Demoralizing Shout.",
    ["41fd2f0"] = "Charge 후 Defensive Stance에 머무세요. 근접으로 때리는 상대에게는 Shield Block, 시전자에게는 Shield Block을 건너뛰세요. 불이 들어올 때마다 Revenge, 오래 사는 몬스터에게는 Rend와 약간의 Sunder Armor, 무리에게는 Thunder Clap과 Demoralizing Shout.",
    ["b604238"] = "Vanguard가 있으면 Defensive Stance에서 Charge를 쓸 수 있습니다. 전투 중이 아니라면 자세를 바꾸지 않고 전투를 시작할 수 있습니다.",
    ["c9e7c22"] = "Shield Wall: 12초 동안 받는 피해 60% 감소. 전투가 나쁘게 흐를 때 쓰세요.",
    ["3f0c2f4"] = "Shield Slam이 가장 강한 타격입니다(피해가 막기 수치에 따라 늘어남). 먼저 쓰고 바로 뒤에 Revenge. 분노가 적으면 Revenge가 먼저입니다. 비용이 더 적습니다.",
    ["846367b"] = "Protection은 무엇보다 힘을 원합니다(한 점당 공격력 2와 막기 수치). 무기는 가장 좋은 DPS를 고르세요. Revenge와 Shield Slam은 무기에 좌우되지 않습니다. 민첩성은 덜 중요합니다. 치명타, 회피, 방어력을 주지만 공격력은 주지 않습니다.",
    ["fabdcb6"] = "먼저 Rend, 그다음 불이 들어올 때마다(대상의 회피 뒤) Overpower.",
    ["f29cf52"] = "Rend, 그다음 불이 들어오면 Overpower. 20레벨부터 타격 직후에 Slam.",
    ["60998aa"] = "Sweeping Strikes: 다음 다섯 번의 타격이 근처의 두 번째 적도 때립니다. 큰 도약입니다. 분노가 남는 동안 한 마리로 시작하고, 이후 두 번째 몬스터를 끌어와 둘에게 Sweeping Strikes와 Cleave를 쓰세요.",
    ["efc030d"] = "Bloodthrill이 있으면 대상에 Rend가 걸려 있을 때 주무기 타격이 20% 확률로 Overpower를 발동시킵니다. Rend는 60레벨까지 연계에 남습니다.",
    ["98a8fec"] = "Mortal Strike가 새로운 주 공격입니다.",
    ["7caf705"] = "무기가 무엇보다 중요합니다. 가장 높은 DPS를 찾고 Arms는 느린 양손 무기(타격과 Mortal Strike, Slam의 피해가 커짐). 나머지는 먼저 적중(빗나간 타격은 피해도 분노도 주지 않음), 그다음 힘과 치명타. 민첩성은 치명타와 회피를 주지만 공격력은 주지 않습니다.",
    ["ce62f29"] = "오래 사는 몬스터에게 Rend, 대상이 회피하면 Overpower. 대상 옆에 두 번째 몬스터가 있으면 남는 분노를 Cleave에 쓰세요. 빠른 보조 손 무기를 고르세요. 타격이 많을수록 분노가 많아집니다.",
    ["1879df1"] = "Death Wish: 30초 동안 물리 피해 20% 증가에 공포에 걸리지 않지만 받는 피해가 5% 늘어납니다. Reckless Swings(31): 체력을 조금 쓰고 다음 네 번의 타격이 분노를 5씩 더 줍니다.",
    ["0d27ce4"] = "Whirlwind(36레벨)가 있으면 몬스터 하나를 상대할 때도 주 버튼입니다. 재사용이 8초로 줄고 가장 가까운 적을 30% 더 큰 피해로 때립니다.",
    ["308a3c5"] = "Whirlwind가 재사용 중일 때마다 Bloodthirst. 50레벨부터 Recklessness가 있습니다.",
    ["2d76abd"] = "무기가 무엇보다 중요합니다. 가장 높은 DPS를 찾으세요. 보조 손은 빠른 것(타격이 많을수록 분노가 많아짐). 나머지는 먼저 적중, 그다음 힘과 치명타. 민첩성은 치명타와 회피를 주지만 공격력은 주지 않습니다.",
}
